// SPDX-License-Identifier: MPL-2.0
//! Time zones (`docs/THINK-2026-11-02-time-zones.md`): UTC ↔ local time for a
//! zone from the IANA tz database, DST included. Pure: no allocation, no
//! syscall, `no_std`. Host KATs: `tools/tz-logic-tests` (mounted by
//! `#[path]`), every expected value worked out by hand.
//!
//! The table (`tz_table.rs`) is generated by `cargo xtask tzdata` from a
//! tz release and checked in. Each zone carries its **final POSIX TZ rule**
//! (the footer `zic` writes into its TZif file), parsed at generation time,
//! so nothing here parses strings. That rule is exact for every time after
//! the release's last explicit transition in the zone, which covers the
//! present; an earlier date converts with the final rule (THINK §2.4).
//!
//! Offsets are seconds **east** of UTC (New York in winter is -18000).

/// One DST transition: day `weekday` (0 = Sunday) of week `week` (1..=4, or
/// 5 = the last) of `month` (1..=12), at `time` seconds after local midnight
/// in the offset in force before the transition. `time` may be negative or
/// past 24 h (RFC 8536 §3.3.1): `America/Nuuk` changes at -1:00.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Transition {
    pub month: u8,
    pub week: u8,
    pub weekday: u8,
    pub time: i32,
}

/// The daylight half of a rule.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Dst {
    pub offset: i32,
    pub abbr: &'static str,
    /// Into DST (local standard time).
    pub start: Transition,
    /// Out of DST (local daylight time).
    pub end: Transition,
}

/// A zone's rule: standard time, and DST if the zone observes it.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Rule {
    pub std_offset: i32,
    pub std_abbr: &'static str,
    pub dst: Option<Dst>,
}

/// A zone in the table. Its index is its stable id ([`ZoneId`]).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Zone {
    pub name: &'static str,
    pub rule: Rule,
}

/// A stable zone id: the index into [`ZONES`]. Ids are append-only across
/// tz releases; 0 is `UTC`.
pub type ZoneId = u16;

/// The offset in force at an instant.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Offset {
    pub seconds: i32,
    pub abbr: &'static str,
    /// The rule's DST part is in force. Not "summer time": a zone with
    /// negative DST has it in winter (Europe/Dublin: GMT in winter is DST,
    /// IST in summer is standard). Show `abbr`; don't infer a season.
    pub is_dst: bool,
}

/// A local wall time read back as UTC.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum LocalResult {
    /// Exactly one instant shows this wall time.
    Single(i64),
    /// Two instants do (the repeated hour when clocks go back): the earlier
    /// and the later.
    Ambiguous(i64, i64),
    /// None does (the hour skipped when clocks go forward). The two readings:
    /// with the offset in force before the gap, and with the one after it.
    Gap {
        offset_before: i64,
        offset_after: i64,
    },
}

mod table {
    use super::{Dst, Rule, Transition, Zone, ZoneId};
    include!("tz_table.rs");
}

#[allow(unused_imports)] // the host test crate mounts this file without using every name
pub use table::{LINKS, TZDATA_COMMIT, TZDATA_VERSION, ZONES};

/// The id of `UTC`.
pub const UTC: ZoneId = 0;

/// The zone with this id.
pub fn zone(id: ZoneId) -> Option<&'static Zone> {
    ZONES.get(id as usize)
}

/// A zone by IANA name or alias, ignoring ASCII case (`america/new_york`,
/// `US/Eastern`).
pub fn zone_by_name(name: &str) -> Option<ZoneId> {
    if let Some(i) = ZONES.iter().position(|z| z.name.eq_ignore_ascii_case(name)) {
        return Some(i as ZoneId);
    }
    LINKS
        .iter()
        .find(|(alias, _)| alias.eq_ignore_ascii_case(name))
        .map(|&(_, id)| id)
}

/// Days from 1970-01-01 to `y-m-d` (proleptic Gregorian; Hinnant's
/// days-from-civil).
pub const fn days_from_civil(y: i64, m: u32, d: u32) -> i64 {
    let y = if m <= 2 { y - 1 } else { y };
    let era = if y >= 0 { y } else { y - 399 } / 400;
    let yoe = y - era * 400;
    let mp = (m as i64 + 9) % 12;
    let doy = (153 * mp + 2) / 5 + d as i64 - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    era * 146097 + doe - 719468
}

/// The civil year containing day `days` since 1970-01-01.
const fn year_of(days: i64) -> i64 {
    let z = days + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = z - era * 146097;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    yoe + era * 400 + if m <= 2 { 1 } else { 0 }
}

const fn is_leap(y: i64) -> bool {
    (y % 4 == 0 && y % 100 != 0) || y % 400 == 0
}

const fn month_days(y: i64, m: u8) -> u32 {
    match m {
        2 => {
            if is_leap(y) {
                29
            } else {
                28
            }
        }
        4 | 6 | 9 | 11 => 30,
        _ => 31,
    }
}

/// Seconds since 1970 (local, as if UTC) of a transition's day in year `y`,
/// plus its time.
fn transition_local(t: Transition, y: i64) -> i64 {
    let first = days_from_civil(y, t.month as u32, 1);
    // 1970-01-01 was a Thursday (4).
    let first_wd = (first + 4).rem_euclid(7);
    let mut day = 1 + (t.weekday as i64 - first_wd).rem_euclid(7);
    day += 7 * (t.week as i64 - 1);
    let last = month_days(y, t.month) as i64;
    while day > last {
        day -= 7;
    }
    (first + day - 1) * 86400 + t.time as i64
}

/// The instants the rule arithmetic evaluates: ±2^40 s (about ±34,800
/// years). An instant outside is evaluated at the nearest bound (the final
/// rule repeats every year, so the offset is that year's), and results are
/// saturated, so every function here is defined, and never overflows, for
/// any `i64` (Dexter, #59).
pub const INSTANT_MAX: i64 = 1 << 40;
pub const INSTANT_MIN: i64 = -INSTANT_MAX;

const fn clamp(t: i64) -> i64 {
    if t < INSTANT_MIN {
        INSTANT_MIN
    } else if t > INSTANT_MAX {
        INSTANT_MAX
    } else {
        t
    }
}

/// The offset in force at `utc` (seconds since 1970, UTC).
pub fn offset_at(rule: &Rule, utc: i64) -> Offset {
    let utc = clamp(utc);
    let standard = Offset {
        seconds: rule.std_offset,
        abbr: rule.std_abbr,
        is_dst: false,
    };
    let Some(dst) = rule.dst else {
        return standard;
    };
    let year = year_of((utc + rule.std_offset as i64).div_euclid(86400));
    // Each transition is checked in the year of the instant and its
    // neighbours, so a transition time past midnight of 31 December (or
    // before 1 January) still lands in the right year.
    let mut in_dst = false;
    let mut latest = i64::MIN;
    for y in [year - 1, year, year + 1] {
        let start = transition_local(dst.start, y) - rule.std_offset as i64;
        let end = transition_local(dst.end, y) - dst.offset as i64;
        if start <= utc && start > latest {
            latest = start;
            in_dst = true;
        }
        if end <= utc && end > latest {
            latest = end;
            in_dst = false;
        }
    }
    if in_dst {
        Offset {
            seconds: dst.offset,
            abbr: dst.abbr,
            is_dst: true,
        }
    } else {
        standard
    }
}

/// `utc` as local seconds (local wall time counted as if UTC) and the offset.
pub fn utc_to_local(utc: i64, id: ZoneId) -> (i64, Offset) {
    let rule = zone(id).map_or(ZONES[0].rule, |z| z.rule);
    let offset = offset_at(&rule, utc);
    (utc.saturating_add(offset.seconds as i64), offset)
}

/// A local wall time (seconds since 1970, counted as if UTC) as UTC.
pub fn local_to_utc(local: i64, id: ZoneId) -> LocalResult {
    let rule = zone(id).map_or(ZONES[0].rule, |z| z.rule);
    let Some(dst) = rule.dst else {
        return LocalResult::Single(local.saturating_sub(rule.std_offset as i64));
    };
    let as_std = local.saturating_sub(rule.std_offset as i64);
    let as_dst = local.saturating_sub(dst.offset as i64);
    let std_ok = offset_at(&rule, as_std).seconds == rule.std_offset;
    let dst_ok = offset_at(&rule, as_dst).seconds == dst.offset;
    match (std_ok, dst_ok) {
        (true, true) => LocalResult::Ambiguous(as_std.min(as_dst), as_std.max(as_dst)),
        (true, false) => LocalResult::Single(as_std),
        (false, true) => LocalResult::Single(as_dst),
        (false, false) => {
            // In the gap: the offset before it is the one in force a day
            // earlier (longer than any gap).
            let before = offset_at(&rule, as_std.min(as_dst).saturating_sub(86400)).seconds as i64;
            let after = if before == rule.std_offset as i64 {
                dst.offset as i64
            } else {
                rule.std_offset as i64
            };
            LocalResult::Gap {
                offset_before: local.saturating_sub(before),
                offset_after: local.saturating_sub(after),
            }
        }
    }
}
